            last=loadrows('-shared-predelete.jsonl.gz');delta=differences(last,shared)
            report['shared']['own_predelete_delta']=zipped('-shared-v3-predelete-to-after-delta.jsonl.gz',delta)
            report['shared']['own_predelete_strict_equal']=not delta
            assert not delta,'shared changed during deletion'
        else:
            assert ROOT.absolute()==ROOT.resolve(strict=True)
            report['ancestors']=ancestors(ROOT)
            owned,summary=scan([ROOT])
            report['owned']={'summary':summary,'snapshot':zipped('-owned-predelete.jsonl.gz',owned)}
            old=namedrows('W1-bs02-independent-cleanup-v2-owned-predelete.jsonl.gz')
            delta=differences(old,owned)
            report['owned']['v2_predelete_delta']=zipped('-owned-v2-predelete-to-predelete-delta.jsonl.gz',delta)
            report['owned']['only_exact_authorized_helper_delta']=delta==auth['authorized_exact_delta']
            expected=namedrows(Path(auth['owned_preparation_snapshot']['path']).name)
            qualified_delta=differences(expected,owned)
            report['owned']['preparation_delta']=zipped('-owned-preparation-to-predelete-delta.jsonl.gz',qualified_delta)
            report['owned']['preparation_strict_equal']=not qualified_delta
            assert delta==auth['authorized_exact_delta'] and not qualified_delta,'additional owned metadata drift'
            for p,h in res['temporary_scripts'].items():assert sha(p)==h,p
            for p,h in auth['all_root_script_sha256'].items():assert sha(p)==h,p
            for row in auth['new_helper_files']:
                assert sha(row['path'])==row['sha256'] and metadata(Path(row['path']))==row['metadata'],row['path']
            report['owned']['audit']=owned_audit(owned)
            report['owned']['link_check']=link_check(owned)
        report['status']='PASS_QUALIFIED_METADATA_OBSERVATION'
    except BaseException as exc:
        report['status']='FAIL';report['error']=repr(exc);raise
    finally:
        report['finished']=time.time();a=write('-'+phase+'.json',report)
        print(json.dumps({'status':report['status'],'phase':phase,'report':a,
            'owned':report.get('owned',{}).get('summary'),
            'shared_v2_equal':report.get('shared',{}).get('v2_predelete_strict_equal'),'error':report.get('error')}))
